{
  "name": "@skwid138/opencode-tui",
  "version": "1.1.1",
  "description": "Configurable TUI plugin for OpenCode — custom logo and prompt placeholders",
  "type": "module",
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "exports": {
    ".": {
      "import": "./dist/config.js",
      "types": "./dist/config.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "vite build",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.50 <3",
    "@opentui/solid": ">=0.2.9 <1",
    "solid-js": "^1.9.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.0",
    "@opentui/solid": "^0.2.9",
    "@opentui/core": "^0.2.9",
    "@opentui/keymap": "^0.2.9",
    "solid-js": "^1.9.0",
    "vite": "^8.0.14",
    "vite-plugin-solid": "^2.0.0",
    "vite-plugin-dts": "^5.0.1",
    "typescript": "^6.0.3",
    "vitest": "^4.1.7",
    "@vitest/coverage-v8": "^4.1.7",
    "semantic-release": "^25.0.0",
    "@types/node": "^22.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/skwid138/opencode-tui.git"
  },
  "homepage": "https://github.com/skwid138/opencode-tui",
  "bugs": {
    "url": "https://github.com/skwid138/opencode-tui/issues"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "plugin",
    "ascii-art",
    "figlet",
    "logo",
    "prompt",
    "terminal"
  ]
}
